#!/usr/bin/env node
/**
 * apply-foundation-advisor.mjs
 *
 * Adds the "Foundation advisor" feature to BuildEstimate:
 *   - AI soil-report reader (you confirm the value before it is used)
 *   - side-by-side comparison of isolated / strip / raft foundations, ranked by cost
 *   - Saved Projects now shows foundation estimates correctly
 *   - realistic minimum footing sizes + raft thickness in foundationFormulas.js
 *
 * Run from your repository root (the folder that contains `backend` and `frontend`):
 *     node apply-foundation-advisor.mjs
 * Safe to run twice. Review with `git diff` before committing.
 */
import fs from 'node:fs';
import path from 'node:path';

const WRITE_FILES = {
 "backend/utils/foundationAdvisor.js": "/**\n * Foundation Advisor\n * Runs isolated, strip and raft sizing for the SAME building + soil, adds an\n * indicative excavation cost, applies practical suitability rules, and ranks\n * the options by cost.\n *\n * Sizing/cost numbers come from foundationFormulas.js (thumb rules). This file\n * never guesses: every ranking and every sentence is derived from those\n * numbers, so the output is repeatable and auditable. It is a planning aid —\n * NOT a substitute for a soil investigation or a structural engineer.\n */\n\nimport { SQFT_PER_SQM } from './formulas.js';\nimport {\n  calculateIsolatedFooting,\n  calculateStripFooting,\n  calculateRaftFoundation,\n  calculateFoundationCost,\n} from './foundationFormulas.js';\n\n// ---- Assumptions (all returned to the caller so nothing is hidden) ---------\nconst PARTITION_LENGTH_FACTOR = 1.5;      // same thumb rule as formulas.js\nconst COLUMN_GRID_AREA_M2 = 14;           // ~one column per 14 m² of plan (≈3.7 m grid)\nconst DEFAULT_FOUNDING_DEPTH_M = 1.5;     // depth of footing base below ground\nconst DEFAULT_EXCAVATION_RATE = 350;      // ₹/m³, indicative — user can edit\nconst WORKING_SPACE_M = 0.3;              // extra excavation each side of a footing\nconst ISOLATED_COVERAGE_LIMIT = 0.5;      // textbook rule: >50% plan coverage → go raft\nconst ISOLATED_COVERAGE_CAUTION = 0.4;\nconst LOW_SBC_T_M2 = 5;\nconst SBC_GRID_T_M2 = [3, 4, 5, 6, 8, 10, 12, 15, 20, 25, 30, 35, 45];\n\nconst LABELS = {\n  isolated: 'Isolated (Pad) Footings',\n  strip: 'Strip (Wall) Footings',\n  raft: 'Raft (Mat) Foundation',\n};\n\nconst round = (n, d = 2) => Number(Number(n).toFixed(d));\nconst inr = (n, cur) => `${cur}${Math.round(n).toLocaleString('en-IN')}`;\n\nexport function soilGrade(sbcTM2) {\n  if (sbcTM2 < 5) return { level: 'very_low', label: 'Very low bearing capacity' };\n  if (sbcTM2 < 10) return { level: 'low', label: 'Low bearing capacity' };\n  if (sbcTM2 < 20) return { level: 'moderate', label: 'Moderate bearing capacity' };\n  if (sbcTM2 < 35) return { level: 'good', label: 'Good bearing capacity' };\n  return { level: 'excellent', label: 'Excellent bearing capacity' };\n}\n\n// ---- Build + price all three options for one set of inputs -------------------\nfunction buildOptions(p, rates) {\n  const footprintM2 = p.builtUpArea / SQFT_PER_SQM;\n  const sideM = Math.sqrt(footprintM2);\n\n  const columnsEstimated = !p.numberOfColumns;\n  const numberOfColumns = p.numberOfColumns || Math.max(4, Math.ceil(footprintM2 / COLUMN_GRID_AREA_M2));\n  const wallLengthEstimated = !p.wallLengthM;\n  const wallLengthM = p.wallLengthM || round(4 * sideM + PARTITION_LENGTH_FACTOR * sideM, 1);\n\n  const common = {\n    builtUpArea: p.builtUpArea,\n    floors: p.floors,\n    soilType: p.soilType,\n    customSbcTM2: p.customSbcTM2,\n    concreteGrade: p.concreteGrade,\n  };\n\n  const raw = {\n    isolated: calculateIsolatedFooting({ ...common, numberOfColumns }),\n    strip: calculateStripFooting({ ...common, wallLengthM }),\n    raft: calculateRaftFoundation({ ...common, plotAreaSqFt: p.plotAreaSqFt }),\n  };\n\n  const depth = p.foundingDepthM;\n  const ws = WORKING_SPACE_M;\n  const excavationM3 = {\n    isolated: numberOfColumns * (raw.isolated.footing.sideM + 2 * ws) ** 2 * depth,\n    strip: (raw.strip.footing.widthM + 2 * ws) * depth * wallLengthM,\n    raft: (Math.sqrt(raw.raft.footing.areaM2) + 2 * ws) ** 2 * depth,\n  };\n\n  const options = {};\n  for (const type of Object.keys(raw)) {\n    const result = raw[type];\n    const { costBreakdown, totalCost: materialCost, combinedMaterials } = calculateFoundationCost(result, rates);\n    const excavCost = Math.round(excavationM3[type] * p.excavationRatePerM3);\n    options[type] = {\n      type,\n      label: LABELS[type],\n      // `result` keeps the same shape as POST /foundation so the existing PDF export works on it\n      result: { ...result, costBreakdown, totalCost: materialCost, combinedMaterials, currency: rates.currency },\n      concreteM3: round(result.totalVolumeM3 + result.pcc.volumeM3, 2),\n      steelTons: result.steelTons,\n      excavationM3: round(excavationM3[type], 1),\n      materialCost,\n      excavationCost: excavCost,\n      totalCost: materialCost + excavCost,\n      notes: [],\n      status: 'alternative',\n    };\n  }\n\n  return {\n    options, footprintM2, numberOfColumns, columnsEstimated, wallLengthM, wallLengthEstimated,\n    sbcTM2: raw.isolated.inputs.sbcTM2,\n    totalLoadKN: raw.isolated.inputs.totalLoadKN,\n    loadPerColumnKN: raw.isolated.inputs.loadPerColumnKN,\n  };\n}\n\n// ---- Practical suitability rules (independent of cost) ----------------------\nfunction applySuitability(built, p) {\n  const { options, footprintM2, sbcTM2 } = built;\n  const { isolated, strip, raft } = options;\n  const framed = p.constructionType !== 'load_bearing';\n\n  // Isolated\n  const coverage = isolated.result.footprintAreaM2 / footprintM2;\n  const covPct = Math.round(coverage * 100);\n  isolated.sizing = `${built.numberOfColumns} footings, ${isolated.result.footing.sideM} × ${isolated.result.footing.sideM} m × ${isolated.result.footing.depthM} m`;\n  isolated.coverage = round(coverage, 2);\n  if (!framed) {\n    isolated.status = 'not_suitable';\n    isolated.notes.push('Load-bearing walls need continuous support — isolated footings suit RCC-framed buildings (columns).');\n  } else if (coverage > ISOLATED_COVERAGE_LIMIT) {\n    isolated.status = 'not_suitable';\n    isolated.notes.push(`Footings would cover ${covPct}% of the plan area. Above ~50% a raft is normally more practical and economical.`);\n  } else if (coverage > ISOLATED_COVERAGE_CAUTION) {\n    isolated.notes.push(`Footings cover ${covPct}% of the plan area — close to the point where a raft becomes the better choice.`);\n  } else {\n    isolated.notes.push(`Footings cover only ${covPct}% of the plan area, which keeps concrete and excavation low.`);\n  }\n\n  // Strip\n  strip.sizing = `${strip.result.footing.widthM} m wide × ${strip.result.footing.depthM} m deep under ${built.wallLengthM} m of walls`;\n  if (framed) {\n    strip.status = 'not_suitable';\n    strip.notes.push('Strip footings carry continuous walls. In an RCC-framed building the columns carry the load, so isolated footings or a raft are the normal choice.');\n  } else {\n    strip.notes.push('Natural fit for load-bearing wall construction.');\n    if (p.floors > 3) {\n      strip.notes.push('Load-bearing masonry is usually limited to about 3 storeys — have an engineer confirm this height.');\n    }\n  }\n\n  // Raft\n  raft.sizing = `${raft.result.footing.areaM2} m² slab, ${Math.round(raft.result.footing.thicknessM * 1000)} mm thick`;\n  if (sbcTM2 < 10) {\n    raft.notes.push('Spreads the load over the whole footprint — helpful on weaker soil and for limiting uneven settlement.');\n  } else if (sbcTM2 >= 20) {\n    raft.notes.push('On soil this strong a raft is usually more concrete than the building needs.');\n  } else {\n    raft.notes.push('Covers the full footprint, so it uses the most concrete and excavation of the three.');\n  }\n}\n\nfunction rank(options) {\n  const suitable = Object.values(options).filter((o) => o.status !== 'not_suitable').sort((a, b) => a.totalCost - b.totalCost);\n  return { suitable, best: suitable[0] };\n}\n\n// ---- What-if: which option wins at other bearing capacities ------------------\nfunction sensitivity(p, rates, currentSbcTM2) {\n  const points = [];\n  for (const sbc of SBC_GRID_T_M2) {\n    const built = buildOptions({ ...p, soilType: undefined, customSbcTM2: sbc }, rates);\n    applySuitability(built, p);\n    points.push({ sbcTM2: sbc, best: rank(built.options).best.type });\n  }\n  const ranges = [];\n  for (const pt of points) {\n    const last = ranges[ranges.length - 1];\n    if (last && last.best === pt.best) last.toSbcTM2 = pt.sbcTM2;\n    else ranges.push({ fromSbcTM2: pt.sbcTM2, toSbcTM2: pt.sbcTM2, best: pt.best });\n  }\n  let summary;\n  if (ranges.length === 1) {\n    summary = `${LABELS[ranges[0].best]} stay the most economical choice across the whole range of soils (3–45 t/m²) for this building.`;\n  } else {\n    const parts = ranges.map((r) => `${r.fromSbcTM2 === r.toSbcTM2 ? r.fromSbcTM2 : `${r.fromSbcTM2}–${r.toSbcTM2}`} t/m²: ${LABELS[r.best]}`);\n    summary = `Cheapest suitable option as soil strength changes — ${parts.join('; ')}. Your soil: ${round(currentSbcTM2, 1)} t/m².`;\n  }\n  return { ranges, summary };\n}\n\n// ---- Public API ---------------------------------------------------------------\n/**\n * @param {object} params\n *   builtUpArea (sq.ft per floor), floors, constructionType ('framed'|'load_bearing'),\n *   soilType | customSbcTM2, concreteGrade, numberOfColumns?, wallLengthM?, plotAreaSqFt?,\n *   foundingDepthM?, excavationRatePerM3?, waterTableDepthM?, soilDescription?, reportRecommendation?\n * @param {object} rates  { cementRatePerBag, sandRatePerTon, aggregateRatePerTon, steelRatePerKg, currency }\n */\nexport function compareFoundations(params, rates) {\n  const p = {\n    ...params,\n    constructionType: params.constructionType === 'load_bearing' ? 'load_bearing' : 'framed',\n    concreteGrade: params.concreteGrade || 'M20',\n    foundingDepthM: params.foundingDepthM || DEFAULT_FOUNDING_DEPTH_M,\n    excavationRatePerM3: params.excavationRatePerM3 || DEFAULT_EXCAVATION_RATE,\n  };\n  const cur = rates.currency || '₹';\n\n  const built = buildOptions(p, rates);\n  applySuitability(built, p);\n  const { suitable, best } = rank(built.options);\n  best.status = 'recommended';\n  const next = suitable[1];\n\n  // ---- Reasons (all derived from the numbers above) ----\n  const grade = soilGrade(built.sbcTM2);\n  const reasons = [];\n  if (next) {\n    const saving = next.totalCost - best.totalCost;\n    const pct = Math.round((saving / next.totalCost) * 100);\n    reasons.push(`About ${inr(saving, cur)} (${pct}%) cheaper than the next-best suitable option, ${next.label}.`);\n  } else {\n    reasons.push('It is the only option that fits this building and soil.');\n  }\n  reasons.push(...best.notes);\n  reasons.push(`${grade.label} (${round(built.sbcTM2, 1)} t/m²) for a ${p.floors}-floor building of about ${Math.round(p.builtUpArea)} sq.ft per floor.`);\n\n  // ---- Warnings ----\n  const warnings = [];\n  if (built.sbcTM2 < LOW_SBC_T_M2) {\n    warnings.push('Bearing capacity is very low. Shallow foundations may be inadequate — ask a geotechnical engineer whether piles or ground improvement are needed. Piles are not covered by this tool.');\n  }\n  if (p.floors > 4) {\n    warnings.push('Buildings above 4 floors are outside what thumb-rule sizing can reliably cover — they need an engineered foundation design (often a raft or piles).');\n  }\n  if (p.waterTableDepthM != null && p.waterTableDepthM < p.foundingDepthM + 0.5) {\n    warnings.push(`Groundwater was reported at ${p.waterTableDepthM} m, close to the founding depth (${p.foundingDepthM} m). Dewatering, waterproofing and a different foundation design may be needed; their cost is not included.`);\n  }\n  if (p.soilDescription && /black\\s*cotton|expansive|swell|made\\s*ground|filled|fill\\b|peat|organic/i.test(p.soilDescription)) {\n    warnings.push(`The soil report mentions \"${p.soilDescription}\". Expansive, filled or organic soils usually need special treatment — follow your geotechnical engineer's advice.`);\n  }\n  if (p.reportRecommendation) {\n    warnings.push(`Your soil report itself recommends: \"${p.reportRecommendation}\". Follow the geotechnical engineer's recommendation wherever it differs from this estimate.`);\n  }\n\n  // Order: recommended, other suitable (cheapest first), then not suitable\n  const ordered = [\n    best,\n    ...suitable.slice(1),\n    ...Object.values(built.options).filter((o) => o.status === 'not_suitable'),\n  ];\n\n  return {\n    currency: cur,\n    inputs: {\n      builtUpArea: p.builtUpArea,\n      floors: p.floors,\n      constructionType: p.constructionType,\n      sbcTM2: round(built.sbcTM2, 1),\n      soil: grade,\n      footprintM2: round(built.footprintM2, 1),\n      totalLoadKN: built.totalLoadKN,\n      foundingDepthM: p.foundingDepthM,\n      excavationRatePerM3: p.excavationRatePerM3,\n    },\n    assumptions: {\n      numberOfColumns: built.numberOfColumns,\n      columnsEstimated: built.columnsEstimated,\n      wallLengthM: built.wallLengthM,\n      wallLengthEstimated: built.wallLengthEstimated,\n    },\n    recommended: best.type,\n    headline: `${best.label} look like the most economical suitable choice.`,\n    reasons,\n    warnings,\n    options: ordered,\n    sensitivity: sensitivity(p, rates, built.sbcTM2),\n    costNote: 'Costs cover concrete materials (incl. a PCC bed), steel and an indicative excavation allowance. Shuttering, labour, plinth beams and dewatering are not included.',\n    disclaimer: 'Preliminary thumb-rule comparison for planning only. Foundation type and design must be confirmed by a structural engineer using an actual soil investigation report.',\n  };\n}\n",
 "backend/utils/soilReportAnalysis.js": "/**\n * Soil report reader.\n * Sends an image of a soil investigation / geotechnical report page to the\n * NVIDIA-hosted vision model and extracts the bearing-capacity values printed\n * on it.\n *\n * Design rule: the model only TRANSCRIBES what is printed (value + unit +\n * depth). Unit conversion, plausibility checks and choosing a default are done\n * here in code, and the user confirms the value in the UI before it is used.\n */\n\nimport { getModel, DEFAULT_MODEL } from './planAnalysis.js';\n\nconst NVIDIA_API_URL = 'https://integrate.api.nvidia.com/v1/chat/completions';\nconst ACCEPTED_MIME_TYPES = new Set(['image/jpeg', 'image/png']);\nconst MAX_BASE64_CHARS = 180_000;\nconst FETCH_TIMEOUT_MS = Number(process.env.NVIDIA_TIMEOUT_MS) || 45_000;\n\nconst MIN_PLAUSIBLE_T_M2 = 1;\nconst MAX_PLAUSIBLE_T_M2 = 150;\nconst KN_PER_TONNE = 9.81;\n\nconst SYSTEM_PROMPT = `You are a JSON API for a civil-engineering tool. You are shown an image of a page\nfrom a soil investigation / geotechnical report (it may be a table, a scan or a photo).\nFind the safe or allowable bearing capacity (SBC) values the report states.\n\nReply with ONE JSON object and nothing else, with exactly these keys:\n{\"readings\":[{\"label\":string|null,\"depthM\":number|null,\"value\":number,\"unit\":string}],\n \"soilDescription\":string|null,\"waterTableDepthM\":number|null,\n \"reportRecommendation\":string|null,\"confidence\":number,\"notes\":string}\n\nRules:\n- readings: every safe/allowable bearing capacity value printed on the page, at most 8. Give the unit\n  exactly as printed (for example \"kN/m2\", \"kPa\", \"t/m2\", \"kg/cm2\", \"MPa\"). Include the depth in metres\n  and the borehole / test-pit label if shown.\n- Copy numbers exactly as printed. Do NOT convert units, calculate or estimate. If a number is not\n  clearly printed, leave it out.\n- If the page shows no bearing capacity value, return \"readings\": [] and say so in notes.\n- soilDescription: one short phrase for the soil strata if stated (e.g. \"medium dense silty sand\"), else null.\n- waterTableDepthM: depth to groundwater in metres if stated, else null.\n- reportRecommendation: the foundation type/depth the report itself recommends, if stated, else null.\n- confidence: 0 to 1 for how legible and unambiguous the values were.\n- notes: one short sentence; mention any ambiguity.`;\n\n// ---- Pure helpers (exported so they can be tested without the network) -------\n\nexport function normalizeUnit(raw) {\n  if (!raw) return null;\n  const u = String(raw).toLowerCase().replace(/²/g, '2').replace(/[\\s.^]/g, '');\n  if (/kpa/.test(u) || /kn/.test(u)) return 'kn_m2';\n  if (/(kgf|kg)/.test(u) && /cm/.test(u)) return 'kg_cm2';\n  if (/mpa/.test(u) || /n\\/mm2/.test(u)) return 'mpa';\n  if (/^(t|ton|tons|tonne|tonnes|mt)\\/?(sq)?m(2|etre|eter)?$/.test(u) || /^t\\/?sqm$/.test(u)) return 't_m2';\n  return null;\n}\n\nexport function toTonnesPerM2(value, unitKey) {\n  switch (unitKey) {\n    case 'kn_m2': return value / KN_PER_TONNE;\n    case 't_m2': return value;\n    case 'kg_cm2': return value * 10;\n    case 'mpa': return (value * 1000) / KN_PER_TONNE;\n    default: return null;\n  }\n}\n\nfunction extractJson(text) {\n  const cleaned = String(text).replace(/```json|```/g, '').trim();\n  const start = cleaned.indexOf('{');\n  const end = cleaned.lastIndexOf('}');\n  if (start === -1 || end === -1) throw new Error('No JSON object in model response');\n  return JSON.parse(cleaned.slice(start, end + 1));\n}\n\nconst cleanText = (v, max = 200) => {\n  if (typeof v !== 'string') return null;\n  const t = v.replace(/[\\u0000-\\u001f]+/g, ' ').trim().slice(0, max);\n  return t || null;\n};\nconst numOrNull = (v) => {\n  const n = typeof v === 'string' ? parseFloat(v) : v;\n  return Number.isFinite(n) ? n : null;\n};\n\n/** Turns the model's raw JSON into validated, unit-converted readings. */\nexport function sanitizeSoilExtraction(raw) {\n  const list = Array.isArray(raw?.readings) ? raw.readings.slice(0, 8) : [];\n  const readings = [];\n  for (const r of list) {\n    const value = numOrNull(r?.value);\n    const unitKey = normalizeUnit(r?.unit);\n    if (value === null || value <= 0 || !unitKey) continue;\n    const sbcTM2 = toTonnesPerM2(value, unitKey);\n    const plausible = sbcTM2 >= MIN_PLAUSIBLE_T_M2 && sbcTM2 <= MAX_PLAUSIBLE_T_M2;\n    readings.push({\n      label: cleanText(r?.label, 60),\n      depthM: numOrNull(r?.depthM),\n      printedValue: value,\n      printedUnit: cleanText(r?.unit, 20),\n      sbcTM2: Math.round(sbcTM2 * 10) / 10,\n      plausible,\n    });\n  }\n\n  const usable = readings.filter((r) => r.plausible);\n  // Conservative default: the lowest plausible value on the page\n  const defaultSbcTM2 = usable.length ? Math.min(...usable.map((r) => r.sbcTM2)) : null;\n\n  const conf = numOrNull(raw?.confidence);\n  return {\n    readings,\n    defaultSbcTM2,\n    soilDescription: cleanText(raw?.soilDescription),\n    waterTableDepthM: numOrNull(raw?.waterTableDepthM),\n    reportRecommendation: cleanText(raw?.reportRecommendation, 240),\n    confidence: conf === null ? 0.5 : Math.max(0, Math.min(1, conf)),\n    notes: cleanText(raw?.notes, 240) || '',\n  };\n}\n\n// ---- Network call ---------------------------------------------------------------\n\nasync function callNvidia(apiKey, dataUrl, { withJsonMode, model }) {\n  const controller = new AbortController();\n  const timeoutId = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);\n\n  const body = {\n    model,\n    messages: [\n      { role: 'system', content: SYSTEM_PROMPT },\n      {\n        role: 'user',\n        content: [\n          { type: 'text', text: 'Extract the bearing capacity values from this soil report page as instructed. Reply with the JSON object only.' },\n          { type: 'image_url', image_url: { url: dataUrl } },\n        ],\n      },\n    ],\n    max_tokens: 1500,\n    temperature: 0.1,\n    top_p: 0.7,\n  };\n  if (withJsonMode) body.response_format = { type: 'json_object' };\n\n  try {\n    return await fetch(NVIDIA_API_URL, {\n      method: 'POST',\n      signal: controller.signal,\n      headers: {\n        'Content-Type': 'application/json',\n        Authorization: `Bearer ${apiKey}`,\n        Accept: 'application/json',\n      },\n      body: JSON.stringify(body),\n    });\n  } catch (fetchErr) {\n    if (fetchErr.name === 'AbortError') {\n      const err = new Error(`NVIDIA API took too long to respond (${model}). Try again or enter the value manually.`);\n      err.status = 504;\n      err.code = 'TIMEOUT';\n      throw err;\n    }\n    const err = new Error(`Could not reach NVIDIA API: ${fetchErr.message}`);\n    err.status = 502;\n    throw err;\n  } finally {\n    clearTimeout(timeoutId);\n  }\n}\n\n/**\n * @param {Buffer} fileBuffer\n * @param {string} mimetype\n * @returns {Promise<object>} sanitized extraction (see sanitizeSoilExtraction)\n */\nexport async function analyzeSoilReport(fileBuffer, mimetype) {\n  if (!ACCEPTED_MIME_TYPES.has(mimetype)) {\n    const err = new Error('Unsupported file type. Upload a JPEG or PNG image of the soil report page.');\n    err.status = 400;\n    throw err;\n  }\n\n  const apiKey = process.env.NVIDIA_API_KEY;\n  if (!apiKey) {\n    const err = new Error('Soil report reading is not configured on this server (missing NVIDIA_API_KEY).');\n    err.status = 503;\n    throw err;\n  }\n\n  const base64Data = fileBuffer.toString('base64');\n  if (base64Data.length > MAX_BASE64_CHARS) {\n    const err = new Error('Image is too large for inline analysis. Please upload a smaller or cropped image.');\n    err.status = 413;\n    throw err;\n  }\n  const dataUrl = `data:${mimetype};base64,${base64Data}`;\n\n  const selectedModel = getModel();\n\n  async function attemptCall(model) {\n    let resp = await callNvidia(apiKey, dataUrl, { withJsonMode: true, model });\n    if (resp.status === 400) resp = await callNvidia(apiKey, dataUrl, { withJsonMode: false, model });\n    return resp;\n  }\n\n  let response;\n  try {\n    response = await attemptCall(selectedModel);\n    if (!response.ok && response.status === 404 && selectedModel !== DEFAULT_MODEL) {\n      console.warn(`Model \"${selectedModel}\" returned 404 on NVIDIA API. Falling back to \"${DEFAULT_MODEL}\"...`);\n      response = await attemptCall(DEFAULT_MODEL);\n    }\n  } catch (err) {\n    if (err.code === 'TIMEOUT' && selectedModel !== DEFAULT_MODEL) {\n      console.warn(`Model \"${selectedModel}\" timed out on NVIDIA API. Falling back to \"${DEFAULT_MODEL}\"...`);\n      response = await attemptCall(DEFAULT_MODEL);\n    } else {\n      throw err;\n    }\n  }\n\n  if (!response.ok) {\n    const bodyText = await response.text().catch(() => '');\n    const err = new Error(`NVIDIA API error (${response.status}): ${bodyText.slice(0, 300)}`);\n    err.status = 502;\n    throw err;\n  }\n\n  const data = await response.json();\n  const text = data?.choices?.[0]?.message?.content;\n  if (!text) {\n    const err = new Error('Model returned no readable text');\n    err.status = 502;\n    throw err;\n  }\n\n  let raw;\n  try {\n    raw = extractJson(text);\n  } catch {\n    const err = new Error(\"Couldn't read a clear result from this page. Try a sharper image of the page with the bearing capacity table, or enter the value manually.\");\n    err.status = 422;\n    throw err;\n  }\n\n  const extracted = sanitizeSoilExtraction(raw);\n  if (!extracted.readings.some((r) => r.plausible)) {\n    const err = new Error(\n      extracted.readings.length\n        ? 'Found numbers, but none looked like a realistic bearing capacity. Check the units on the report and enter the value manually.'\n        : \"Couldn't find a bearing capacity value on this page. Try the page with the SBC table, or enter the value manually.\"\n    );\n    err.status = 422;\n    throw err;\n  }\n  return extracted;\n}\n",
 "backend/utils/foundationFormulas.js": "/**\n * Foundation Estimation Logic & Formulas\n * Thumb-rule preliminary sizing for isolated, strip, and raft foundations —\n * same spirit as formulas.js: fast estimates for planning/costing, NOT a\n * substitute for a geotechnical report or a structural engineer's design.\n *\n * All inputs are validated by the caller (see routes/api.js).\n */\n\nimport { SQFT_PER_SQM, calculateConcreteMix } from './formulas.js';\n\n// ---- Soil bearing capacity presets (IS 1904 style indicative ranges) -----\n// Values are the LOWER/typical end of each range — conservative on purpose.\n// sbcKNm2 is what calculations use; sbcTM2 is only for display (Indian\n// practice usually quotes bearing capacity in tonnes/m²).\nexport const SOIL_PRESETS = {\n  soft_clay: { label: 'Soft Clay / Made-up / Filled Ground', sbcTM2: 5 },\n  loose_sand: { label: 'Loose Sand / Soft Silt', sbcTM2: 8 },\n  medium_clay: { label: 'Medium Clay / Medium Dense Sand', sbcTM2: 10 },\n  stiff_clay: { label: 'Stiff Clay / Dense Sand', sbcTM2: 20 },\n  gravel: { label: 'Gravel / Very Dense Sand', sbcTM2: 25 },\n  soft_rock: { label: 'Soft Rock / Weathered Rock', sbcTM2: 35 },\n  hard_rock: { label: 'Hard Rock', sbcTM2: 45 },\n};\nconst T_M2_TO_KN_M2 = 9.81;\nfor (const key of Object.keys(SOIL_PRESETS)) {\n  SOIL_PRESETS[key].sbcKNm2 = Math.round(SOIL_PRESETS[key].sbcTM2 * T_M2_TO_KN_M2);\n}\n\n// ---- Thumb-rule constants -------------------------------------------------\nconst LOAD_PER_SQM_PER_FLOOR_KN = 12.5; // dead + live load, residential RCC frame, per floor\nconst WALL_LOAD_PER_M_PER_FLOOR_KN = 12; // load-bearing wall construction, per running metre per floor\nconst FOOTING_SELF_WEIGHT_FACTOR = 1.10; // adds ~10% for footing's own weight when sizing\n\nconst MIN_ISOLATED_DEPTH_M = 0.3;\nconst MIN_STRIP_DEPTH_M = 0.3;\nconst MIN_STRIP_WIDTH_M = 0.45;    // practical minimum under a 230 mm wall\nconst MIN_ISOLATED_SIDE_M = 0.9;   // practical minimum pad size\nconst MIN_RAFT_THICKNESS_M = 0.25;\nconst MAX_RAFT_THICKNESS_M = 0.6;\n\nconst ISOLATED_FOOTING_STEEL_KG_PER_M3 = 80;  // indicative, ~0.5-1% by volume\nconst STRIP_FOOTING_STEEL_KG_PER_M3 = 65;\nconst RAFT_STEEL_KG_PER_M3 = 100;             // mat foundations carry top + bottom steel\n\nconst PCC_BED_THICKNESS_M = 0.075; // 75 mm plain concrete leveling/blinding course\nconst PCC_GRADE = 'M10';\n\nconst round = (n, d = 2) => Number(n.toFixed(d));\n// round a dimension UP to the nearest 0.05 m so it's a buildable size\nconst roundUpTo5cm = (n) => Math.ceil(n * 20) / 20;\n\nfunction resolveSbcKNm2({ soilType, customSbcTM2 }) {\n  if (customSbcTM2 !== undefined && customSbcTM2 !== null && customSbcTM2 !== '') {\n    const v = Number(customSbcTM2);\n    return { sbcKNm2: v * T_M2_TO_KN_M2, sbcTM2: v, source: 'custom' };\n  }\n  const preset = SOIL_PRESETS[soilType] || SOIL_PRESETS.medium_clay;\n  return { sbcKNm2: preset.sbcKNm2, sbcTM2: preset.sbcTM2, source: soilType || 'medium_clay' };\n}\n\nfunction totalBuildingLoadKN(builtUpAreaSqFtPerFloor, floors) {\n  const totalSqFt = Number(builtUpAreaSqFtPerFloor) * Number(floors);\n  const totalSqM = totalSqFt / SQFT_PER_SQM;\n  return totalSqM * LOAD_PER_SQM_PER_FLOOR_KN;\n}\n\nfunction pccQuantities(footprintAreaM2) {\n  const volumeM3 = round(footprintAreaM2 * PCC_BED_THICKNESS_M, 3);\n  return { thicknessM: PCC_BED_THICKNESS_M, volumeM3, mix: calculateConcreteMix(volumeM3, PCC_GRADE) };\n}\n\n// ---- Isolated (pad) footing -----------------------------------------------\n/**\n * params: builtUpArea (sqft/floor), floors, numberOfColumns,\n *         soilType | customSbcTM2, concreteGrade\n */\nexport function calculateIsolatedFooting(params) {\n  const {\n    builtUpArea, floors, numberOfColumns,\n    soilType, customSbcTM2, concreteGrade = 'M20',\n  } = params;\n\n  const { sbcKNm2, sbcTM2, source } = resolveSbcKNm2({ soilType, customSbcTM2 });\n  const totalLoadKN = totalBuildingLoadKN(builtUpArea, floors);\n  const loadPerColumnKN = totalLoadKN / Number(numberOfColumns);\n  const factoredLoadKN = loadPerColumnKN * FOOTING_SELF_WEIGHT_FACTOR;\n\n  const rawAreaM2 = factoredLoadKN / sbcKNm2;\n  const sideM = Math.max(MIN_ISOLATED_SIDE_M, roundUpTo5cm(Math.sqrt(rawAreaM2)));\n  const depthM = roundUpTo5cm(Math.max(MIN_ISOLATED_DEPTH_M, sideM / 5));\n\n  const perFootingVolumeM3 = round(sideM * sideM * depthM, 3);\n  const totalVolumeM3 = round(perFootingVolumeM3 * Number(numberOfColumns), 3);\n  const steelKg = Math.ceil(totalVolumeM3 * ISOLATED_FOOTING_STEEL_KG_PER_M3);\n\n  const footprintAreaM2 = round(sideM * sideM * Number(numberOfColumns), 2);\n\n  return {\n    foundationType: 'isolated',\n    inputs: {\n      numberOfColumns: Number(numberOfColumns),\n      totalLoadKN: round(totalLoadKN),\n      loadPerColumnKN: round(loadPerColumnKN),\n      sbcTM2: round(sbcTM2), sbcKNm2: round(sbcKNm2), soilSource: source,\n    },\n    footing: { sideM, depthM, perFootingVolumeM3 },\n    totalVolumeM3,\n    concrete: calculateConcreteMix(totalVolumeM3, concreteGrade),\n    steelKg, steelTons: round(steelKg / 1000),\n    pcc: pccQuantities(footprintAreaM2),\n    footprintAreaM2,\n  };\n}\n\n// ---- Strip (wall) footing --------------------------------------------------\n/**\n * params: builtUpArea (sqft/floor), floors, wallLengthM (total load-bearing\n *         wall length at foundation level), soilType | customSbcTM2, concreteGrade\n */\nexport function calculateStripFooting(params) {\n  const {\n    builtUpArea, floors, wallLengthM,\n    soilType, customSbcTM2, concreteGrade = 'M20',\n  } = params;\n\n  const { sbcKNm2, sbcTM2, source } = resolveSbcKNm2({ soilType, customSbcTM2 });\n  const lengthM = Number(wallLengthM);\n\n  // Load per metre run: derive from total building load spread over wall length\n  const totalLoadKN = totalBuildingLoadKN(builtUpArea, floors);\n  const derivedLoadPerM = totalLoadKN / lengthM;\n  // Sanity floor so unrealistic short wall lengths don't collapse the estimate\n  const loadPerMKN = Math.max(derivedLoadPerM, WALL_LOAD_PER_M_PER_FLOOR_KN * Number(floors) * 0.5);\n  const factoredLoadPerMKN = loadPerMKN * FOOTING_SELF_WEIGHT_FACTOR;\n\n  const widthM = Math.max(MIN_STRIP_WIDTH_M, roundUpTo5cm(factoredLoadPerMKN / sbcKNm2));\n  const depthM = roundUpTo5cm(Math.max(MIN_STRIP_DEPTH_M, widthM / 3));\n\n  const totalVolumeM3 = round(widthM * depthM * lengthM, 3);\n  const steelKg = Math.ceil(totalVolumeM3 * STRIP_FOOTING_STEEL_KG_PER_M3);\n  const footprintAreaM2 = round(widthM * lengthM, 2);\n\n  return {\n    foundationType: 'strip',\n    inputs: {\n      wallLengthM: lengthM,\n      totalLoadKN: round(totalLoadKN),\n      loadPerMKN: round(loadPerMKN),\n      sbcTM2: round(sbcTM2), sbcKNm2: round(sbcKNm2), soilSource: source,\n    },\n    footing: { widthM, depthM },\n    totalVolumeM3,\n    concrete: calculateConcreteMix(totalVolumeM3, concreteGrade),\n    steelKg, steelTons: round(steelKg / 1000),\n    pcc: pccQuantities(footprintAreaM2),\n    footprintAreaM2,\n  };\n}\n\n// ---- Raft (mat) foundation --------------------------------------------------\n/**\n * params: builtUpArea (sqft/floor), floors, plotAreaSqFt (footprint to cover;\n *         raft is at least as large as the building footprint regardless of\n *         load), soilType | customSbcTM2, concreteGrade\n */\nexport function calculateRaftFoundation(params) {\n  const {\n    builtUpArea, floors, plotAreaSqFt,\n    soilType, customSbcTM2, concreteGrade = 'M20',\n  } = params;\n\n  const { sbcKNm2, sbcTM2, source } = resolveSbcKNm2({ soilType, customSbcTM2 });\n  const totalLoadKN = totalBuildingLoadKN(builtUpArea, floors);\n  const factoredLoadKN = totalLoadKN * FOOTING_SELF_WEIGHT_FACTOR;\n\n  const footprintSqFt = Number(plotAreaSqFt) > 0 ? Number(plotAreaSqFt) : Number(builtUpArea);\n  const footprintM2 = footprintSqFt / SQFT_PER_SQM;\n  const requiredByLoadM2 = factoredLoadKN / sbcKNm2;\n  // A raft is never smaller than the building footprint it sits under\n  const raftAreaM2 = round(Math.max(footprintM2, requiredByLoadM2), 2);\n\n  const thicknessM = roundUpTo5cm(\n    Math.min(MAX_RAFT_THICKNESS_M, Math.max(MIN_RAFT_THICKNESS_M, 0.25 + 0.075 * (Number(floors) - 1)))\n  );\n\n  const totalVolumeM3 = round(raftAreaM2 * thicknessM, 2);\n  const steelKg = Math.ceil(totalVolumeM3 * RAFT_STEEL_KG_PER_M3);\n\n  return {\n    foundationType: 'raft',\n    inputs: {\n      totalLoadKN: round(totalLoadKN),\n      requiredAreaByLoadM2: round(requiredByLoadM2),\n      footprintM2: round(footprintM2),\n      sbcTM2: round(sbcTM2), sbcKNm2: round(sbcKNm2), soilSource: source,\n    },\n    footing: { areaM2: raftAreaM2, thicknessM },\n    totalVolumeM3,\n    concrete: calculateConcreteMix(totalVolumeM3, concreteGrade),\n    steelKg, steelTons: round(steelKg / 1000),\n    pcc: pccQuantities(raftAreaM2),\n    footprintAreaM2: raftAreaM2,\n  };\n}\n\n// ---- Simple heuristic suggestion -------------------------------------------\n// A rough pointer only — never a substitute for an engineer's judgement.\nexport function suggestFoundationType({ floors, soilType, customSbcTM2, constructionType }) {\n  const { sbcTM2 } = resolveSbcKNm2({ soilType, customSbcTM2 });\n  const nFloors = Number(floors) || 1;\n\n  if (sbcTM2 <= 6 || nFloors >= 5) {\n    return { type: 'raft', reason: 'Low soil bearing capacity or a taller building usually needs a raft/mat foundation to spread the load.' };\n  }\n  if (constructionType === 'load_bearing') {\n    return { type: 'strip', reason: 'Load-bearing wall construction is typically supported on continuous strip footings.' };\n  }\n  return { type: 'isolated', reason: 'An RCC-framed building on reasonable soil is typically supported on isolated column footings.' };\n}\n\n// ---- Cost -------------------------------------------------------------------\nexport function calculateFoundationCost(result, rates) {\n  const { concrete, steelKg, pcc } = result;\n  const cementBags = concrete.cementBags + pcc.mix.cementBags;\n  const sandTons = round(concrete.sandTons + pcc.mix.sandTons, 2);\n  const aggregateTons = round(concrete.aggregateTons + pcc.mix.aggregateTons, 2);\n\n  const costBreakdown = {\n    cement: Math.round(cementBags * rates.cementRatePerBag),\n    sand: Math.round(sandTons * rates.sandRatePerTon),\n    aggregate: Math.round(aggregateTons * rates.aggregateRatePerTon),\n    steel: Math.round(steelKg * rates.steelRatePerKg),\n  };\n  const totalCost = Object.values(costBreakdown).reduce((a, b) => a + b, 0);\n  return { costBreakdown, totalCost, combinedMaterials: { cementBags, sandTons, aggregateTons } };\n}",
 "frontend/src/components/FoundationAdvisor.jsx": "import React, { useState, useEffect, useCallback } from 'react';\nimport {\n  fetchSoilTypes,\n  recommendFoundation,\n  downloadFoundationPdf,\n  saveProject,\n} from '../api';\nimport SoilReportUpload from './SoilReportUpload';\n\nconst CONCRETE_GRADES = ['M15', 'M20', 'M25'];\n\nconst STATUS_STYLE = {\n  recommended: { label: 'Best value', cls: 'bg-emerald-100 text-emerald-800 border-emerald-200' },\n  alternative: { label: 'Also workable', cls: 'bg-slate-100 text-slate-700 border-slate-200' },\n  not_suitable: { label: 'Not suitable', cls: 'bg-rose-100 text-rose-700 border-rose-200' },\n};\n\nconst inr = (n, cur = '₹') => `${cur}${Math.round(Number(n) || 0).toLocaleString('en-IN')}`;\n\nexport default function FoundationAdvisor({ rates }) {\n  const [soilTypes, setSoilTypes] = useState([]);\n  const [form, setForm] = useState({\n    builtUpArea: 1000,\n    floors: 2,\n    constructionType: 'framed',\n    soilType: 'medium_clay',\n    customSbcTM2: '',\n    concreteGrade: 'M20',\n    numberOfColumns: '',\n    wallLengthM: '',\n    plotAreaSqFt: '',\n    foundingDepthM: '',\n    excavationRatePerM3: '',\n  });\n  const [soilTab, setSoilTab] = useState('preset'); // preset | custom | report\n  const [reportCtx, setReportCtx] = useState(null); // confirmed soil-report values\n  const [showAdvanced, setShowAdvanced] = useState(false);\n\n  const [result, setResult] = useState(null);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState('');\n\n  const [projectTitle, setProjectTitle] = useState('');\n  const [saveStatus, setSaveStatus] = useState('');\n  const [isSaving, setIsSaving] = useState(false);\n\n  useEffect(() => {\n    fetchSoilTypes().then(setSoilTypes).catch(() => {});\n  }, []);\n\n  const update = (key, value) => setForm((prev) => ({ ...prev, [key]: value }));\n\n  const customSbcValid =\n    Number(form.customSbcTM2) > 0 && Number(form.customSbcTM2) <= 150;\n  const soilReady =\n    soilTab === 'preset' ||\n    (soilTab === 'custom' && customSbcValid) ||\n    (soilTab === 'report' && reportCtx);\n\n  const handleSubmit = useCallback(async (e) => {\n    e.preventDefault();\n    if (!soilReady) return;\n    setError('');\n    setLoading(true);\n    setSaveStatus('');\n    try {\n      const payload = {\n        builtUpArea: Number(form.builtUpArea),\n        floors: Number(form.floors),\n        constructionType: form.constructionType,\n        concreteGrade: form.concreteGrade,\n        numberOfColumns: form.numberOfColumns,\n        wallLengthM: form.wallLengthM,\n        plotAreaSqFt: form.plotAreaSqFt,\n        foundingDepthM: form.foundingDepthM,\n        excavationRatePerM3: form.excavationRatePerM3,\n        rates,\n      };\n      if (soilTab === 'preset') {\n        payload.soilType = form.soilType;\n      } else if (soilTab === 'custom') {\n        payload.customSbcTM2 = Number(form.customSbcTM2);\n      } else {\n        payload.customSbcTM2 = reportCtx.sbcTM2;\n        payload.soilDescription = reportCtx.soilDescription;\n        payload.reportRecommendation = reportCtx.reportRecommendation;\n        if (reportCtx.waterTableDepthM != null) payload.waterTableDepthM = reportCtx.waterTableDepthM;\n      }\n      const data = await recommendFoundation(payload);\n      setResult({ ...data, soilSource: soilTab });\n    } catch (err) {\n      setError(err.message || 'Could not compare foundations.');\n      setResult(null);\n    } finally {\n      setLoading(false);\n    }\n  }, [form, rates, soilReady, soilTab, reportCtx]);\n\n  const best = result ? result.options.find((o) => o.type === result.recommended) : null;\n\n  const handleDownloadPdf = () => {\n    if (!best) return;\n    const r = best.result;\n    downloadFoundationPdf({\n      title: `${best.label} — Recommended Foundation Estimate`,\n      result: r,\n      costBreakdown: r.costBreakdown,\n      totalCost: r.totalCost,\n      currency: r.currency,\n    }).catch((err) => alert(err.message || 'Failed to download PDF.'));\n  };\n\n  const handleSave = async (e) => {\n    e.preventDefault();\n    if (!projectTitle.trim() || !best) return;\n    setIsSaving(true);\n    setSaveStatus('');\n    try {\n      await saveProject({\n        title: projectTitle.trim(),\n        parameters: {\n          foundationType: best.type,\n          builtUpArea: result.inputs.builtUpArea,\n          floors: result.inputs.floors,\n          constructionType: result.inputs.constructionType,\n          sbcTM2: result.inputs.sbcTM2,\n        },\n        results: {\n          ...best.result,\n          advisor: {\n            headline: result.headline,\n            comparison: result.options.map((o) => ({\n              type: o.type, label: o.label, status: o.status, totalCost: o.totalCost,\n            })),\n          },\n        },\n      });\n      setSaveStatus('Saved! 🎉');\n      setProjectTitle('');\n    } catch (err) {\n      setSaveStatus(err.message || 'Failed to save.');\n    } finally {\n      setIsSaving(false);\n    }\n  };\n\n  const tabBtn = (id, label) => (\n    <button\n      type=\"button\"\n      onClick={() => setSoilTab(id)}\n      className={`flex-1 text-xs font-semibold py-1.5 rounded-lg transition ${\n        soilTab === id ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500 hover:text-slate-700'\n      }`}\n    >\n      {label}\n    </button>\n  );\n\n  return (\n    <div className=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n      {/* ---------------- Form ---------------- */}\n      <div className=\"lg:col-span-5 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm\">\n        <h2 className=\"text-xl font-bold text-slate-800 mb-1\">Find the best foundation</h2>\n        <p className=\"text-sm text-slate-500 mb-5\">\n          Tell us about the building and soil. We size isolated, strip and raft foundations side by side and\n          rank the ones that suit your building by cost.\n        </p>\n\n        <form onSubmit={handleSubmit} className=\"space-y-4\">\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label className=\"block text-xs font-semibold text-slate-600 mb-1\">Built-up area / floor (sq.ft)</label>\n              <input type=\"number\" min=\"1\" required value={form.builtUpArea}\n                onChange={(e) => update('builtUpArea', e.target.value)}\n                className=\"w-full border rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500\" />\n            </div>\n            <div>\n              <label className=\"block text-xs font-semibold text-slate-600 mb-1\">Number of floors</label>\n              <input type=\"number\" min=\"1\" max=\"100\" required value={form.floors}\n                onChange={(e) => update('floors', e.target.value)}\n                className=\"w-full border rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500\" />\n            </div>\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-semibold text-slate-600 mb-1\">How is the building built?</label>\n            <div className=\"grid grid-cols-2 gap-2\">\n              {[\n                ['framed', 'RCC frame', 'Columns + beams carry the load'],\n                ['load_bearing', 'Load-bearing walls', 'Masonry walls carry the load'],\n              ].map(([id, label, hint]) => (\n                <button key={id} type=\"button\" onClick={() => update('constructionType', id)}\n                  className={`text-left p-2.5 rounded-xl border transition ${\n                    form.constructionType === id\n                      ? 'border-indigo-500 bg-indigo-50 ring-1 ring-indigo-500'\n                      : 'border-slate-200 hover:border-slate-300 bg-white'\n                  }`}>\n                  <div className=\"text-sm font-bold text-slate-800\">{label}</div>\n                  <div className=\"text-[11px] text-slate-500\">{hint}</div>\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Soil */}\n          <div className=\"bg-slate-50 border border-slate-200 rounded-xl p-3 space-y-3\">\n            <label className=\"text-xs font-semibold text-slate-600\">Soil bearing capacity</label>\n            <div className=\"flex gap-1 bg-slate-200/60 p-1 rounded-xl\">\n              {tabBtn('preset', 'Soil type')}\n              {tabBtn('custom', 'I know the SBC')}\n              {tabBtn('report', 'Upload soil report (AI)')}\n            </div>\n\n            {soilTab === 'preset' && (\n              <select value={form.soilType} onChange={(e) => update('soilType', e.target.value)}\n                className=\"w-full border rounded-lg px-3 py-2 text-sm bg-white outline-none focus:ring-2 focus:ring-indigo-500\">\n                {soilTypes.map((s) => (\n                  <option key={s.key} value={s.key}>{s.label} (~{s.sbcTM2} t/m²)</option>\n                ))}\n              </select>\n            )}\n\n            {soilTab === 'custom' && (\n              <div className=\"flex items-center border rounded-lg px-3 py-2 bg-white\">\n                <input type=\"number\" min=\"0\" step=\"any\" value={form.customSbcTM2}\n                  onChange={(e) => update('customSbcTM2', e.target.value)}\n                  placeholder=\"e.g. 15\" className=\"w-full outline-none text-sm\" />\n                <span className=\"text-xs text-slate-400 ml-2 whitespace-nowrap\">t/m²</span>\n              </div>\n            )}\n\n            {soilTab === 'report' && (\n              <SoilReportUpload\n                onConfirm={setReportCtx}\n                onClear={() => setReportCtx(null)}\n              />\n            )}\n\n            <p className=\"text-[11px] text-slate-400\">\n              1 kg/cm² = 10 t/m² ≈ 98 kN/m². Preset values are typical ranges — a real soil test is always better.\n            </p>\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-semibold text-slate-600 mb-1\">Concrete grade (footing)</label>\n            <select value={form.concreteGrade} onChange={(e) => update('concreteGrade', e.target.value)}\n              className=\"w-full border rounded-lg px-3 py-2 text-sm bg-white outline-none focus:ring-2 focus:ring-indigo-500\">\n              {CONCRETE_GRADES.map((g) => <option key={g} value={g}>{g}</option>)}\n            </select>\n          </div>\n\n          <button type=\"button\" onClick={() => setShowAdvanced((v) => !v)}\n            className=\"text-xs font-semibold text-indigo-600 hover:text-indigo-800\">\n            {showAdvanced ? '− Hide' : '+ Show'} advanced options\n          </button>\n\n          {showAdvanced && (\n            <div className=\"grid grid-cols-2 gap-3 bg-slate-50 border border-slate-200 rounded-xl p-3\">\n              {[\n                ['numberOfColumns', 'Number of columns', 'Auto-estimated'],\n                ['wallLengthM', 'Load-bearing wall length (m)', 'Auto-estimated'],\n                ['plotAreaSqFt', 'Plot / footprint area (sq.ft)', 'Same as built-up'],\n                ['foundingDepthM', 'Founding depth (m)', '1.5'],\n                ['excavationRatePerM3', 'Excavation rate (₹/m³)', '350'],\n              ].map(([key, label, ph]) => (\n                <div key={key}>\n                  <label className=\"block text-[11px] font-semibold text-slate-600 mb-1\">{label}</label>\n                  <input type=\"number\" min=\"0\" step=\"any\" value={form[key]} placeholder={ph}\n                    onChange={(e) => update(key, e.target.value)}\n                    className=\"w-full border rounded-lg px-2.5 py-1.5 text-sm bg-white outline-none focus:ring-2 focus:ring-indigo-500\" />\n                </div>\n              ))}\n              <p className=\"col-span-2 text-[11px] text-slate-400\">\n                Leave blank to use the defaults shown. The excavation rate is indicative — set it for your city.\n              </p>\n            </div>\n          )}\n\n          <button type=\"submit\" disabled={loading || !soilReady}\n            className=\"w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-2.5 rounded-xl transition shadow-sm disabled:opacity-50\">\n            {loading ? 'Comparing…' : 'Find the best foundation'}\n          </button>\n          {soilTab === 'report' && !reportCtx && (\n            <p className=\"text-xs text-amber-600\">Upload a soil report and confirm the value to continue.</p>\n          )}\n          {soilTab === 'custom' && !customSbcValid && (\n            <p className=\"text-xs text-amber-600\">Enter a bearing capacity between 0 and 150 t/m².</p>\n          )}\n          {error && <p className=\"text-sm text-red-600 font-medium\">{error}</p>}\n        </form>\n      </div>\n\n      {/* ---------------- Results ---------------- */}\n      <div className=\"lg:col-span-7\">\n        {!result ? (\n          <div className=\"bg-white p-12 rounded-2xl border border-slate-200 text-center flex flex-col items-center justify-center h-full min-h-[380px] shadow-sm\">\n            <div className=\"w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mb-4 text-3xl\">🧭</div>\n            <h3 className=\"text-xl font-bold text-slate-800 mb-2\">No comparison yet</h3>\n            <p className=\"text-slate-500 text-sm max-w-md\">\n              Enter your building and soil details (or upload a soil report) to see which foundation gives the best\n              value, and why.\n            </p>\n          </div>\n        ) : (\n          <div className=\"bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-5\">\n            {/* Recommendation */}\n            <div className=\"bg-emerald-50 border border-emerald-200 rounded-xl p-4\">\n              <span className=\"text-[11px] font-bold uppercase tracking-wider text-emerald-700\">Recommended</span>\n              <h3 className=\"text-xl font-black text-slate-900 mt-0.5\">{best.label}</h3>\n              <p className=\"text-sm text-slate-600 mt-0.5\">\n                {inr(best.totalCost, result.currency)} <span className=\"text-slate-400\">(materials + excavation)</span>\n              </p>\n              <ul className=\"mt-3 space-y-1 text-sm text-slate-700 list-disc pl-5\">\n                {result.reasons.map((r, i) => <li key={i}>{r}</li>)}\n              </ul>\n            </div>\n\n            <div className=\"text-xs text-slate-600 bg-slate-50 border border-slate-200 rounded-xl p-3\">\n              <strong>{result.inputs.soil.label}</strong> — {result.inputs.sbcTM2} t/m²\n              {result.soilSource === 'report' ? ' (from your soil report)' : ''} · building load ≈{' '}\n              {Math.round(result.inputs.totalLoadKN).toLocaleString('en-IN')} kN · founding depth {result.inputs.foundingDepthM} m\n            </div>\n\n            {result.warnings.length > 0 && (\n              <div className=\"space-y-2\">\n                {result.warnings.map((w, i) => (\n                  <div key={i} className=\"bg-amber-50 border border-amber-200 rounded-xl p-3 text-xs text-amber-800\">\n                    <strong>Check:</strong> {w}\n                  </div>\n                ))}\n              </div>\n            )}\n\n            {/* Comparison */}\n            <div>\n              <h4 className=\"text-sm font-bold text-slate-800 mb-2\">Side-by-side comparison</h4>\n              <div className=\"overflow-x-auto border border-slate-200 rounded-xl\">\n                <table className=\"w-full text-xs min-w-[560px]\">\n                  <thead className=\"bg-slate-50 text-slate-500\">\n                    <tr>\n                      <th className=\"text-left p-2.5 font-semibold\">Foundation</th>\n                      <th className=\"text-right p-2.5 font-semibold\">Concrete</th>\n                      <th className=\"text-right p-2.5 font-semibold\">Steel</th>\n                      <th className=\"text-right p-2.5 font-semibold\">Dig</th>\n                      <th className=\"text-right p-2.5 font-semibold\">Materials</th>\n                      <th className=\"text-right p-2.5 font-semibold\">Excav.</th>\n                      <th className=\"text-right p-2.5 font-semibold\">Total</th>\n                    </tr>\n                  </thead>\n                  <tbody>\n                    {result.options.map((o) => {\n                      const st = STATUS_STYLE[o.status];\n                      const muted = o.status === 'not_suitable';\n                      return (\n                        <React.Fragment key={o.type}>\n                          <tr className={`border-t border-slate-100 ${muted ? 'text-slate-400' : 'text-slate-800'}`}>\n                            <td className=\"p-2.5\">\n                              <div className=\"font-bold\">{o.label}</div>\n                              <span className={`inline-block mt-1 px-2 py-0.5 rounded-full border text-[10px] font-bold ${st.cls}`}>\n                                {st.label}\n                              </span>\n                              <div className=\"text-[11px] text-slate-500 mt-1\">{o.sizing}</div>\n                            </td>\n                            <td className=\"p-2.5 text-right whitespace-nowrap\">{o.concreteM3} m³</td>\n                            <td className=\"p-2.5 text-right whitespace-nowrap\">{o.steelTons} t</td>\n                            <td className=\"p-2.5 text-right whitespace-nowrap\">{o.excavationM3} m³</td>\n                            <td className=\"p-2.5 text-right whitespace-nowrap\">{inr(o.materialCost, result.currency)}</td>\n                            <td className=\"p-2.5 text-right whitespace-nowrap\">{inr(o.excavationCost, result.currency)}</td>\n                            <td className=\"p-2.5 text-right font-bold whitespace-nowrap\">{inr(o.totalCost, result.currency)}</td>\n                          </tr>\n                          <tr className={muted ? 'text-slate-400' : 'text-slate-500'}>\n                            <td colSpan={7} className=\"px-2.5 pb-2.5 text-[11px]\">\n                              {o.notes.join(' ')}\n                            </td>\n                          </tr>\n                        </React.Fragment>\n                      );\n                    })}\n                  </tbody>\n                </table>\n              </div>\n              <p className=\"text-[11px] text-slate-400 mt-2\">{result.costNote}</p>\n            </div>\n\n            {/* What if the soil is different */}\n            <div className=\"text-xs text-slate-600 bg-indigo-50/60 border border-indigo-100 rounded-xl p-3\">\n              <strong>If the soil turns out different:</strong> {result.sensitivity.summary}\n            </div>\n\n            <p className=\"text-[11px] text-slate-400\">\n              Assumed {result.assumptions.numberOfColumns} columns\n              {result.assumptions.columnsEstimated ? ' (estimated)' : ''} and {result.assumptions.wallLengthM} m of\n              load-bearing wall{result.assumptions.wallLengthEstimated ? ' (estimated)' : ''}. Excavation at{' '}\n              {inr(result.inputs.excavationRatePerM3, result.currency)}/m³.\n            </p>\n\n            <div className=\"bg-red-50 border border-red-100 rounded-xl p-3 text-[11px] text-red-700\">\n              {result.disclaimer}\n            </div>\n\n            <div className=\"flex flex-wrap items-center gap-2 border-t border-slate-100 pt-4\">\n              <button onClick={handleDownloadPdf}\n                className=\"px-4 py-2 bg-slate-800 hover:bg-slate-900 text-white text-sm font-semibold rounded-lg transition\">\n                Download PDF (recommended)\n              </button>\n            </div>\n\n            <form onSubmit={handleSave} className=\"flex gap-2\">\n              <input type=\"text\" placeholder=\"Project title (e.g. Site A Foundation)\" value={projectTitle}\n                onChange={(e) => setProjectTitle(e.target.value)} required\n                className=\"flex-1 border rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500\" />\n              <button type=\"submit\" disabled={isSaving}\n                className=\"bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-indigo-700 disabled:opacity-50\">\n                {isSaving ? 'Saving…' : 'Save'}\n              </button>\n            </form>\n            {saveStatus && <p className=\"text-xs text-slate-600 font-medium\">{saveStatus}</p>}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
 "frontend/src/components/FoundationHub.jsx": "import React, { useState } from 'react';\nimport FoundationAdvisor from './FoundationAdvisor';\nimport FoundationEstimator from './FoundationEstimator';\n\nexport default function FoundationHub({ rates }) {\n  const [mode, setMode] = useState('advisor'); // advisor | single\n\n  const pill = (id, label) => (\n    <button\n      type=\"button\"\n      onClick={() => setMode(id)}\n      className={`px-4 py-2 text-sm font-semibold rounded-xl transition ${\n        mode === id ? 'bg-indigo-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'\n      }`}\n    >\n      {label}\n    </button>\n  );\n\n  return (\n    <div>\n      <div className=\"max-w-6xl mx-auto px-6 pt-6 flex flex-wrap gap-2\">\n        {pill('advisor', '🧭 Foundation advisor')}\n        {pill('single', '🧱 Single-type calculator')}\n      </div>\n      {mode === 'advisor' ? (\n        <div className=\"p-6 max-w-6xl mx-auto\">\n          <FoundationAdvisor rates={rates} />\n        </div>\n      ) : (\n        <FoundationEstimator rates={rates} />\n      )}\n    </div>\n  );\n}\n",
 "frontend/src/components/SoilReportUpload.jsx": "import React, { useRef, useState } from 'react';\nimport { analyzeSoilReport } from '../api';\n\n// The vision API takes JPEG/PNG only and small inline images (~130 KB). Soil\n// reports are text-heavy, so keep a larger dimension than the floor-plan\n// uploader and shrink quality/size step by step until it fits.\nconst MAX_BYTES_IN = 25 * 1024 * 1024;\nconst TARGET_BYTES = 120 * 1024;\nconst MAX_DIMENSION = 2000;\n\nfunction loadImage(file) {\n  return new Promise((resolve, reject) => {\n    const img = new Image();\n    img.onload = () => resolve(img);\n    img.onerror = () => reject(new Error('Could not read that image file.'));\n    img.src = URL.createObjectURL(file);\n  });\n}\n\nconst toBlob = (canvas, quality) =>\n  new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', quality));\n\nasync function compressReport(file) {\n  const img = await loadImage(file);\n  try {\n    let scale = Math.min(1, MAX_DIMENSION / Math.max(img.width, img.height));\n    for (let pass = 0; pass < 4; pass += 1) {\n      const canvas = document.createElement('canvas');\n      canvas.width = Math.max(1, Math.round(img.width * scale));\n      canvas.height = Math.max(1, Math.round(img.height * scale));\n      const ctx = canvas.getContext('2d');\n      ctx.fillStyle = '#ffffff';\n      ctx.fillRect(0, 0, canvas.width, canvas.height);\n      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);\n\n      let quality = 0.85;\n      for (let i = 0; i < 5; i += 1) {\n        const blob = await toBlob(canvas, Math.max(quality, 0.3));\n        if (blob && blob.size <= TARGET_BYTES) {\n          return new File([blob], 'soil-report.jpg', { type: 'image/jpeg' });\n        }\n        quality -= 0.14;\n      }\n      scale *= 0.8;\n    }\n    throw new Error('Could not shrink that image enough. Try cropping to just the bearing capacity table.');\n  } finally {\n    URL.revokeObjectURL(img.src);\n  }\n}\n\n/**\n * Props: onConfirm({ sbcTM2, soilDescription, waterTableDepthM, reportRecommendation })\n *        onClear()  — called when the user discards a confirmed value\n */\nexport default function SoilReportUpload({ onConfirm, onClear }) {\n  const inputRef = useRef(null);\n  const [fileName, setFileName] = useState('');\n  const [status, setStatus] = useState('idle'); // idle | compressing | analyzing | review | confirmed | error\n  const [error, setError] = useState('');\n  const [extracted, setExtracted] = useState(null);\n  const [picked, setPicked] = useState(0);\n  const [sbcInput, setSbcInput] = useState('');\n\n  const reset = () => {\n    setFileName('');\n    setStatus('idle');\n    setError('');\n    setExtracted(null);\n    setPicked(0);\n    setSbcInput('');\n    if (inputRef.current) inputRef.current.value = '';\n    onClear && onClear();\n  };\n\n  const handleFile = async (file) => {\n    if (!file) return;\n    if (!file.type.startsWith('image/')) {\n      setStatus('error');\n      setError('Please upload a JPEG or PNG image (a photo or screenshot of the report page). PDFs are not supported yet.');\n      return;\n    }\n    if (file.size > MAX_BYTES_IN) {\n      setStatus('error');\n      setError('File is too large (25 MB max).');\n      return;\n    }\n\n    setFileName(file.name);\n    setStatus('compressing');\n    setError('');\n    try {\n      const compressed = await compressReport(file);\n      setStatus('analyzing');\n      const data = await analyzeSoilReport(compressed);\n      setExtracted(data);\n      // Default to the lowest plausible reading (conservative)\n      const firstBest = data.readings.findIndex((r) => r.plausible && r.sbcTM2 === data.defaultSbcTM2);\n      const idx = firstBest >= 0 ? firstBest : 0;\n      setPicked(idx);\n      setSbcInput(String(data.readings[idx]?.sbcTM2 ?? data.defaultSbcTM2 ?? ''));\n      setStatus('review');\n    } catch (err) {\n      console.error(err);\n      setStatus('error');\n      setError(err.message || 'Could not read this soil report.');\n    }\n  };\n\n  const pickReading = (i) => {\n    setPicked(i);\n    setSbcInput(String(extracted.readings[i].sbcTM2));\n  };\n\n  const sbcValue = Number(sbcInput);\n  const sbcValid = Number.isFinite(sbcValue) && sbcValue >= 1 && sbcValue <= 150;\n\n  const confirm = () => {\n    if (!sbcValid) return;\n    setStatus('confirmed');\n    onConfirm({\n      sbcTM2: sbcValue,\n      soilDescription: extracted.soilDescription || '',\n      waterTableDepthM: extracted.waterTableDepthM,\n      reportRecommendation: extracted.reportRecommendation || '',\n    });\n  };\n\n  return (\n    <div className=\"space-y-3\">\n      <div className=\"flex items-center gap-2\">\n        <input\n          ref={inputRef}\n          type=\"file\"\n          accept=\"image/jpeg,image/png,image/*\"\n          onChange={(e) => handleFile(e.target.files?.[0])}\n          className=\"hidden\"\n          id=\"soil-report-input\"\n        />\n        <label\n          htmlFor=\"soil-report-input\"\n          className=\"cursor-pointer text-sm font-semibold bg-white border border-indigo-200 text-indigo-700 hover:bg-indigo-50 px-4 py-2 rounded-xl transition-colors\"\n        >\n          {fileName ? 'Choose another' : 'Choose soil report image'}\n        </label>\n        {fileName && <span className=\"text-xs text-slate-500 truncate max-w-[10rem]\">{fileName}</span>}\n        {status !== 'idle' && (\n          <button type=\"button\" onClick={reset} className=\"text-xs text-slate-400 hover:text-slate-600 ml-auto\">\n            Clear\n          </button>\n        )}\n      </div>\n      <p className=\"text-[11px] text-slate-400\">\n        Upload a photo or screenshot of the report page that shows the safe bearing capacity (SBC) table. Cropping to\n        just that table gives the best reading.\n      </p>\n\n      {status === 'compressing' && <p className=\"text-xs text-indigo-600 font-medium animate-pulse\">Preparing image…</p>}\n      {status === 'analyzing' && <p className=\"text-xs text-indigo-600 font-medium animate-pulse\">Reading the soil report…</p>}\n      {status === 'error' && <p className=\"text-xs text-red-600 font-medium\">{error}</p>}\n\n      {status === 'review' && extracted && (\n        <div className=\"bg-white border border-indigo-100 rounded-xl p-3 space-y-3 text-xs\">\n          <div>\n            <p className=\"font-semibold text-slate-700\">\n              Here is what the AI read — please check it against your report\n            </p>\n            <p className=\"text-slate-400\">AI can misread digits or units. Confidence {Math.round(extracted.confidence * 100)}%.</p>\n          </div>\n\n          <div className=\"space-y-1.5\">\n            {extracted.readings.map((r, i) => (\n              <label\n                key={i}\n                className={`flex items-start gap-2 p-2 rounded-lg border cursor-pointer ${\n                  picked === i ? 'border-indigo-400 bg-indigo-50' : 'border-slate-200'\n                } ${r.plausible ? '' : 'opacity-50 cursor-not-allowed'}`}\n              >\n                <input\n                  type=\"radio\"\n                  name=\"soil-reading\"\n                  checked={picked === i}\n                  disabled={!r.plausible}\n                  onChange={() => pickReading(i)}\n                  className=\"mt-0.5\"\n                />\n                <span className=\"text-slate-700\">\n                  {r.label ? <strong>{r.label}</strong> : 'Reading'}\n                  {r.depthM != null ? ` · ${r.depthM} m deep` : ''}\n                  <br />\n                  Printed: {r.printedValue} {r.printedUnit} → <strong>{r.sbcTM2} t/m²</strong>\n                  {!r.plausible && <span className=\"text-red-600\"> (unrealistic — ignored)</span>}\n                </span>\n              </label>\n            ))}\n          </div>\n\n          <div>\n            <label className=\"block font-semibold text-slate-600 mb-1\">Bearing capacity to use (t/m²)</label>\n            <input\n              type=\"number\"\n              step=\"any\"\n              min=\"1\"\n              max=\"150\"\n              value={sbcInput}\n              onChange={(e) => setSbcInput(e.target.value)}\n              className=\"w-full border rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500\"\n            />\n            <p className=\"text-slate-400 mt-1\">\n              The lowest reading is pre-selected because it is the safest choice. You can edit it.\n            </p>\n          </div>\n\n          {(extracted.soilDescription || extracted.waterTableDepthM != null || extracted.reportRecommendation) && (\n            <div className=\"bg-slate-50 border border-slate-200 rounded-lg p-2 space-y-0.5 text-slate-600\">\n              {extracted.soilDescription && <p>Soil: <strong>{extracted.soilDescription}</strong></p>}\n              {extracted.waterTableDepthM != null && <p>Water table: <strong>{extracted.waterTableDepthM} m</strong></p>}\n              {extracted.reportRecommendation && <p>Report recommends: <strong>{extracted.reportRecommendation}</strong></p>}\n            </div>\n          )}\n          {extracted.notes && <p className=\"text-amber-600 italic\">{extracted.notes}</p>}\n\n          <button\n            type=\"button\"\n            onClick={confirm}\n            disabled={!sbcValid}\n            className=\"w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-2 rounded-lg disabled:opacity-50\"\n          >\n            Use {sbcValid ? `${sbcValue} t/m²` : 'this value'}\n          </button>\n        </div>\n      )}\n\n      {status === 'confirmed' && (\n        <div className=\"bg-emerald-50 border border-emerald-200 rounded-xl p-3 text-xs text-emerald-800\">\n          Using <strong>{sbcValue} t/m²</strong> from your soil report. Click <em>Clear</em> to choose a different one.\n        </div>\n      )}\n    </div>\n  );\n}\n"
};
